319	    /**
320	     * Stripe Checkout hosted setup flow for collecting a reusable payment method.
321	     */
322	    public function createPaymentMethodSetupCheckoutSession(
323	        Professional $brand,
324	        string $successUrl,
325	        string $cancelUrl,
326	    ): array {
327	        $customerId = $brand->stripe_customer_id;
328	
329	        if (! $customerId) {
330	            $customerId = $this->createCustomer($brand);
331	        }
332	
333	        $session = $this->stripe->checkout->sessions->create([
334	            'mode' => 'setup',
335	            'customer' => $customerId,
336	            'payment_method_types' => ['card'],
337	            'success_url' => $this->appendCheckoutSessionParam($successUrl, 'stripe_pm_session_id'),
338	            'cancel_url' => $cancelUrl,
339	            'metadata' => [
340	                'purpose' => 'brand_commission_payment_method',
341	                'sidest_professional_id' => $brand->id,
342	            ],
343	        ]);
344	
345	        return [
346	            'checkout_url' => $session->url,
347	            'session_id' => $session->id,
348	        ];
349	    }
