351	    /**
352	     * Sync payment method from a completed hosted setup session.
353	     */
354	    public function syncPaymentMethodFromCheckoutSession(Professional $brand, string $sessionId): array
355	    {
356	        $session = $this->stripe->checkout->sessions->retrieve($sessionId, [
357	            'expand' => ['setup_intent'],
358	        ]);
359	
360	        if (($session->mode ?? null) !== 'setup') {
361	            throw new \RuntimeException('Checkout session is not a setup session.');
362	        }
363	
364	        if (($session->status ?? null) !== 'complete') {
365	            throw new \RuntimeException('Setup session is not complete yet.');
366	        }
367	
368	        $metadataProId = $session->metadata?->sidest_professional_id ?? null;
369	        if ($metadataProId && $metadataProId !== $brand->id) {
370	            throw new \RuntimeException('Setup session does not belong to this account.');
371	        }
372	
373	        $sessionCustomerId = is_string($session->customer)
374	            ? $session->customer
375	            : ($session->customer->id ?? null);
376	
377	        if ($brand->stripe_customer_id && $sessionCustomerId && $brand->stripe_customer_id !== $sessionCustomerId) {
378	            throw new \RuntimeException('Setup session customer does not match account customer.');
379	        }
380	
381	        if (! $brand->stripe_customer_id && $sessionCustomerId) {
382	            $brand->update(['stripe_customer_id' => $sessionCustomerId]);
383	            $brand->refresh();
384	        }
385	
386	        $setupIntentId = is_string($session->setup_intent)
387	            ? $session->setup_intent
388	            : ($session->setup_intent->id ?? null);
