13	// V2: Stripe Connect Express onboarding, payment methods, commission wallet top-ups, and payout history. Required for the 80/20 affiliate payout split.
14	class StripeConnectController extends Controller
15	{
16	    public function __construct(
17	        private readonly StripeConnectService $connectService,
18	        private readonly CommissionPayoutService $payoutService,
19	    ) {}
20	
21	    /**
22	     * GET /stripe/status
23	     * Returns the current Stripe Connect/Customer status for the professional.
24	     */
25	    public function status(Request $request): JsonResponse
26	    {
27	        $pro = $request->attributes->get('professional');
28	
29	        // ?fresh=1 forces a live Stripe round-trip — used immediately after the
30	        // Stripe Connect onboarding redirect so the dashboard never renders a
31	        // pre-onboarding cache hit while the account.updated webhook is in flight.
32	        if ($request->boolean('fresh') && $pro->stripe_connect_account_id) {
33	            StripeConnectService::forgetStatusCache($pro->stripe_connect_account_id);
34	        }
35	
36	        $connectStatus = $this->connectService->syncAccountStatus($pro);
37	        $hasPaymentMethod = $this->connectService->brandHasPaymentMethod($pro);
38	        $pro->refresh();
39	
40	        return response()->json([
41	            'connect' => $connectStatus,
42	            'has_payment_method' => $hasPaymentMethod,
43	            'stripe_customer_id' => $pro->stripe_customer_id,
44	            'funding_mode' => $pro->stripe_commission_funding_mode ?? 'auto_charge',
45	            'manual_balance' => [
46	                'cents' => (int) ($pro->stripe_manual_balance_cents ?? 0),
47	                'currency_code' => strtoupper((string) ($pro->stripe_manual_balance_currency ?: 'AUD')),
48	            ],
49	        ]);
50	    }
51	
52	    /**
53	     * POST /stripe/connect/onboard
54	     * Creates a Connect Express account and returns the onboarding URL.
55	     * Used by professionals/influencers to receive payouts.
56	     */
57	    public function onboard(Request $request): JsonResponse
58	    {
59	        $request->validate([
60	            'return_url' => 'required|url',
61	            'refresh_url' => 'required|url',
62	        ]);
63	
64	        $pro = $request->attributes->get('professional');
65	
66	        $url = $this->connectService->createOnboardingLink(
67	            $pro,
68	            $request->input('return_url'),
69	            $request->input('refresh_url'),
70	        );
71	
72	        return response()->json(['onboarding_url' => $url]);
73	    }
74	
75	    /**
76	     * POST /stripe/connect/dashboard
77	     * Returns a Stripe Express dashboard login link.
78	     */
79	    public function dashboard(Request $request): JsonResponse
80	    {
81	        $pro = $request->attributes->get('professional');
82	
83	        $url = $this->connectService->createDashboardLink($pro);
84	
85	        if (! $url) {
86	            return response()->json(['error' => 'Dashboard not available. Complete onboarding first.'], 422);
87	        }
88	
89	        return response()->json(['dashboard_url' => $url]);
90	    }
91	
92	    /**
93	     * POST /stripe/connect/disconnect
94	     * Disconnects the Connect account from the platform.
95	     */
96	    public function disconnect(Request $request): JsonResponse
97	    {
98	        $pro = $request->attributes->get('professional');
99	
100	        if (! $pro->stripe_connect_account_id) {
101	            return response()->json(['error' => 'No Stripe Connect account to disconnect.'], 422);
102	        }
103	
104	        $this->connectService->disconnectAccount($pro);
105	
106	        return response()->json(['status' => 'disconnected']);
107	    }
