109	    /**
110	     * POST /stripe/payment-method/setup
111	     * Creates a SetupIntent so the brand can save a payment method.
112	     */
113	    public function setupPaymentMethod(Request $request): JsonResponse
114	    {
115	        $pro = $request->attributes->get('professional');
