21	    /**
22	     * Cache TTL (seconds) for the syncAccountStatus payload. Short on purpose:
23	     * Stripe Connect status changes are eventual via webhooks, so a 60s window
24	     * bounds how long a non-onboarding caller can see stale charges_enabled /
25	     * payouts_enabled data when the account.updated webhook is in transit.
26	     */
27	    private const STATUS_CACHE_TTL = 60;
28	
29	    public function __construct(private readonly CacheLockService $cacheLock)
30	    {
31	        $this->stripe = new StripeClient(config('services.stripe.secret_key'));
32	    }
