34	    /**
35	     * Cache key for a connected account's status payload. Keyed on the Stripe
36	     * account ID (not the professional ID) so the webhook bust path can
37	     * forget the cache without a DB lookup — the webhook already carries the
38	     * account ID in event->account.
39	     *
40	     * Static so the webhook handler can bust the cache without instantiating
41	     * the service (which would force-load the Stripe SDK with a real secret).
42	     */
43	    public static function statusCacheKey(string $accountId): string
44	    {
45	        return 'stripe:connect:status:'.$accountId;
46	    }
47	
48	    /**
49	     * Evict the cached account status. MUST clear the SWR ":stale" copy too —
50	     * forgetting only the primary key would leave the stale-while-revalidate
51	     * last-good copy live for up to 10×TTL, defeating the bust entirely.
52	     *
53	     * Called from:
54	     *   - StripeConnectController@status when the request includes ?fresh=1
55	     *     (post-onboarding redirect; user must see live state, not cached).
56	     *   - StripeConnectWebhookController on every account.updated event.
57	     */
58	    public static function forgetStatusCache(string $accountId): void
59	    {
60	        $key = self::statusCacheKey($accountId);
61	        Cache::forget($key);
62	        Cache::forget($key.':stale');
63	    }
