65	    /**
66	     * Create a Stripe Connect Express account for a professional/influencer/brand.
67	     *
68	     * Requires country_code to be set on the professional. Without it the
69	     * account would silently default to 'AU' and Stripe would later reject
70	     * the KYC form for non-AU users. Fail fast instead so the frontend can
71	     * prompt for country before onboarding.
72	     */
73	    public function createConnectAccount(Professional $professional): string
74	    {
75	        if (! is_string($professional->country_code) || trim($professional->country_code) === '') {
76	            abort(
77	                422,
78	                'Cannot create a Stripe Connect account without a country. Please set your country on your profile before connecting Stripe.'
79	            );
80	        }
81	
82	        $account = $this->stripe->accounts->create([
83	            'type' => 'express',
84	            'country' => $this->mapCountryCode($professional->country_code),
85	            'email' => $professional->primary_email,
86	            // Affiliates are individuals/sole traders — pre-selects the individual
87	            // KYC path so Stripe doesn't prompt with a business-type selector.
88	            'business_type' => 'individual',
89	            'metadata' => [
90	                'sidest_professional_id' => $professional->id,
91	                'professional_type' => $professional->professional_type,
92	            ],
93	            'capabilities' => [
94	                'transfers' => ['requested' => true],
95	                'card_payments' => ['requested' => true],
96	            ],
97	        ], ['idempotency_key' => "acct_{$professional->id}"]);
98	
99	        $update = [
100	            'stripe_connect_account_id' => $account->id,
101	            'stripe_connect_status' => 'onboarding',
102	            'stripe_grace_period_ends_at' => $professional->stripe_grace_period_ends_at
103	                ?? now()->addDays((int) config('partna.store.grace_period_days', 30)),
104	        ];
105	
106	        // Seed wallet currency from Shopify's shop_currency so brands with
107	        // non-AUD stores don't get locked into the AUD DB default.
108	        $shopCurrency = $this->resolveShopCurrency($professional);
109	        if ($shopCurrency) {
110	            $update['stripe_manual_balance_currency'] = $shopCurrency;
111	        }
112	
113	        $professional->update($update);
114	
115	        return $account->id;
116	    }
