118	    /**
119	     * Generate an onboarding link for a Connect Express account.
120	     *
121	     * If the professional previously soft-disconnected (status='disconnected'
122	     * but account_id preserved), reset their status to 'onboarding' so the
123	     * webhook handler stops skipping updates and the next account.updated
124	     * event flows through normally. Stripe KYC is preserved on the account,
125	     * so reconnecting is typically a one-click flow.
126	     */
127	    public function createOnboardingLink(Professional $professional, string $returnUrl, string $refreshUrl): string
128	    {
129	        $accountId = $professional->stripe_connect_account_id;
130	
131	        if (! $accountId) {
132	            $accountId = $this->createConnectAccount($professional);
133	        } else {
134	            if ($professional->stripe_connect_status === 'disconnected') {
135	                $professional->update(['stripe_connect_status' => 'onboarding']);
136	            }
137	
138	            // Patch business_type to 'individual' on any existing account that
139	            // hasn't finished onboarding yet. Stripe permits this update while
140	            // details_submitted is false — once submitted it's locked in.
141	            try {
142	                $existing = $this->stripe->accounts->retrieve($accountId);
143	                if (! $existing->details_submitted && $existing->business_type !== 'individual') {
144	                    $this->stripe->accounts->update($accountId, ['business_type' => 'individual']);
145	                }
146	            } catch (ApiErrorException) {
147	                // Non-fatal — continue with existing account as-is.
148	            }
149	        }
150	
151	        // Inject ?fresh=1 so the dashboard's first /stripe/status call after
152	        // Stripe redirects the user back skips the cache. Without this the
153	        // post-onboarding screen would race the account.updated webhook and
154	        // typically render the pre-onboarding state for several seconds.
155	        $returnUrlWithBypass = $returnUrl.(str_contains($returnUrl, '?') ? '&' : '?').'fresh=1';
156	
157	        $link = $this->stripe->accountLinks->create([
158	            'account' => $accountId,
159	            'refresh_url' => $refreshUrl,
160	            'return_url' => $returnUrlWithBypass,
161	            'type' => 'account_onboarding',
162	        ]);
163	
164	        return $link->url;
165	    }
