167	    /**
168	     * Check the status of a Connect account and sync it locally.
169	     *
170	     * If the professional is in the locally-disconnected state, we skip the
171	     * Stripe round-trip entirely — their account still exists at Stripe and
172	     * would return 'active', but the user has explicitly opted out. Let them
173	     * stay disconnected until they reconnect via createOnboardingLink.
174	     */
175	    public function syncAccountStatus(Professional $professional): array
176	    {
177	        $accountId = $professional->stripe_connect_account_id;
178	
179	        if (! $accountId) {
180	            return [
181	                'status' => 'not_connected',
182	                'charges_enabled' => false,
183	                'payouts_enabled' => false,
184	                'details_submitted' => false,
185	            ];
186	        }
187	
188	        if ($professional->stripe_connect_status === 'disconnected') {
189	            return [
190	                'status' => 'disconnected',
191	                'charges_enabled' => false,
192	                'payouts_enabled' => false,
193	                'details_submitted' => false,
194	            ];
195	        }
196	
197	        // Cache wraps the Stripe round-trip only — the early-return branches
198	        // above are already free. Bust paths: ?fresh=1 on the controller
199	        // (post-onboarding redirect) and account.updated webhook.
200	        return $this->cacheLock->rememberLocked(
201	            self::statusCacheKey($accountId),
202	            self::STATUS_CACHE_TTL,
203	            fn () => $this->fetchAndSyncAccountStatus($professional, $accountId),
204	        );
205	    }
