207	    /**
208	     * Inner closure for syncAccountStatus — single Stripe call + DB sync, then
209	     * the response shape consumed by /api/stripe/status.
210	     *
211	     * @return array{status: string, charges_enabled: bool, payouts_enabled: bool, details_submitted: bool, requirements: array<int, string>}
212	     */
213	    private function fetchAndSyncAccountStatus(Professional $professional, string $accountId): array
214	    {
215	        $account = $this->stripe->accounts->retrieve($accountId);
216	
217	        $status = self::determineAccountStatus($account);
218	
219	        if ($professional->stripe_connect_status !== $status) {
220	            $professional->update(['stripe_connect_status' => $status]);
221	        }
222	
223	        return [
224	            'status' => $status,
225	            'charges_enabled' => (bool) $account->charges_enabled,
226	            'payouts_enabled' => (bool) $account->payouts_enabled,
227	            'details_submitted' => (bool) $account->details_submitted,
228	            'requirements' => $account->requirements?->currently_due ?? [],
229	        ];
230	    }
