546	    /**
547	     * Confirm a completed top-up Checkout session and credit the brand balance.
548	     * Idempotent by checkout session id.
549	     */
550	    public function confirmManualTopUpCheckoutSession(Professional $brand, string $sessionId): array
551	    {
552	        $existing = BrandCommissionTopup::query()
553	            ->where('stripe_checkout_session_id', $sessionId)
554	            ->first();
555	
556	        if ($existing) {
557	            $brand->refresh();
558	
559	            return [
560	                'status' => 'already_applied',
561	                'balance_cents' => (int) ($brand->stripe_manual_balance_cents ?? 0),
562	                'currency_code' => strtoupper((string) ($brand->stripe_manual_balance_currency ?: 'AUD')),
563	                'topup_id' => $existing->id,
564	            ];
565	        }
566	
567	        $session = $this->stripe->checkout->sessions->retrieve($sessionId);
568	
569	        if (($session->mode ?? null) !== 'payment') {
570	            throw new \RuntimeException('Checkout session is not a payment session.');
571	        }
572	
573	        if (($session->payment_status ?? null) !== 'paid') {
574	            throw new \RuntimeException('Top-up payment is not completed yet.');
575	        }
576	
577	        $metadataProId = $session->metadata?->sidest_professional_id ?? null;
578	        if ($metadataProId && $metadataProId !== $brand->id) {
579	            throw new \RuntimeException('Top-up session does not belong to this account.');
580	        }
581	
582	        $purpose = $session->metadata?->purpose ?? null;
583	        if ($purpose !== 'brand_commission_topup') {
584	            throw new \RuntimeException('Invalid top-up session purpose.');
585	        }
586	
587	        $amountCents = (int) ($session->amount_total ?? 0);
588	        if ($amountCents <= 0) {
589	            throw new \RuntimeException('Top-up amount is invalid.');
590	        }
591	
592	        $currency = strtoupper((string) ($session->currency ?: ($brand->stripe_manual_balance_currency ?: 'AUD')));
593	        $paymentIntentId = is_string($session->payment_intent)
594	            ? $session->payment_intent
595	            : ($session->payment_intent->id ?? null);
596	
597	        return DB::transaction(function () use ($brand, $sessionId, $paymentIntentId, $amountCents, $currency) {
598	            $lockedBrand = Professional::query()
599	                ->whereKey($brand->id)
600	                ->lockForUpdate()
601	                ->firstOrFail();
602	
603	            $existingTopup = BrandCommissionTopup::query()
604	                ->where('stripe_checkout_session_id', $sessionId)
605	                ->first();
606	
607	            if ($existingTopup) {
608	                return [
609	                    'status' => 'already_applied',
610	                    'balance_cents' => (int) ($lockedBrand->stripe_manual_balance_cents ?? 0),
611	                    'currency_code' => strtoupper((string) ($lockedBrand->stripe_manual_balance_currency ?: 'AUD')),
612	                    'topup_id' => $existingTopup->id,
613	                ];
614	            }
615	
616	            $currentBalance = (int) ($lockedBrand->stripe_manual_balance_cents ?? 0);
617	            $currentCurrency = strtoupper((string) ($lockedBrand->stripe_manual_balance_currency ?: $currency));
618	
619	            if ($currentCurrency !== $currency && $currentBalance > 0) {
620	                throw new \RuntimeException(
621	                    sprintf(
622	                        'Top-up currency %s does not match existing wallet currency %s.',
623	                        $currency,
624	                        $currentCurrency,
625	                    )
626	                );
627	            }
628	
629	            $currencyChanged = $currentCurrency !== $currency;
630	
631	            if ($currencyChanged) {
632	                $lockedBrand->stripe_manual_balance_currency = $currency;
633	            }
634	
635	            $lockedBrand->stripe_manual_balance_cents = $currentBalance + $amountCents;
636	            $lockedBrand->save();
637	
638	            $topup = BrandCommissionTopup::create([
639	                'brand_professional_id' => $lockedBrand->id,
640	                'stripe_checkout_session_id' => $sessionId,
641	                'stripe_payment_intent_id' => $paymentIntentId,
642	                'amount_cents' => $amountCents,
643	                'currency_code' => $currency,
644	                'status' => 'completed',
645	            ]);
646	
647	            if ($currencyChanged) {
648	                WalletCurrencySwitchAudit::create([
649	                    'professional_id' => $lockedBrand->id,
650	                    'previous_currency' => $currentCurrency,
651	                    'new_currency' => $currency,
652	                    'actor_type' => WalletCurrencySwitchAudit::ACTOR_TYPE_SYSTEM,
653	                    'topup_id' => $topup->id,
654	                    'metadata' => ['trigger' => 'top_up_empty_balance'],
655	                ]);
656	            }
657	
658	            return [
659	                'status' => 'applied',
660	                'balance_cents' => (int) $lockedBrand->stripe_manual_balance_cents,
661	                'currency_code' => strtoupper((string) $lockedBrand->stripe_manual_balance_currency),
662	                'topup_id' => $topup->id,
663	            ];
664	        });
665	    }
