667	    private function appendCheckoutSessionParam(string $url, string $param): string
668	    {
669	        $separator = str_contains($url, '?') ? '&' : '?';
670	
671	        return $url.$separator.$param.'={CHECKOUT_SESSION_ID}';
672	    }
