674	    /**
675	     * Determine the Connect account status from a Stripe Account object.
676	     * Shared by both the service and the webhook controller.
677	     */
678	    public static function determineAccountStatus(object $account): string
679	    {
680	        if ($account->charges_enabled && $account->payouts_enabled && $account->details_submitted) {
681	            return 'active';
682	        }
683	
684	        if ($account->requirements?->disabled_reason ?? null) {
685	            return 'restricted';
686	        }
687	
688	        return 'onboarding';
689	    }
