691	    /**
692	     * Resolve the shop currency from the professional's Shopify integration, if present.
693	     * Returns null when no Shopify integration exists or shop_currency is not yet set.
694	     */
695	    private function resolveShopCurrency(Professional $professional): ?string
696	    {
697	        $integration = ProfessionalIntegration::query()
698	            ->where('professional_id', $professional->id)
699	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
700	            ->first();
701	
702	        if (! $integration) {
703	            return null;
704	        }
705	
706	        $currency = Arr::get($integration->provider_metadata ?? [], 'shop_currency');
707	
708	        return ($currency && is_string($currency)) ? strtoupper(trim($currency)) : null;
709	    }
